/// <summary>
/// DTO: SanguoRegionDefinition
/// Description: Region metadata and region-wide bonus definition.
/// </summary>
/// <remarks>
/// EffectKind is restricted by an allow-list in quality gates.
/// </remarks>
public sealed record SanguoRegionDefinition(
    string RegionId,
    string NameKey,
    string DescriptionKey,
    string EffectKind,
    IReadOnlyDictionary<string, string> EffectParams,
    SanguoEconomyStepDeltas EconomyStepDeltas
);

using System;
using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace Game.Core.Contracts.Sanguo;

/// <summary>
/// DTO: SanguoRelicsCatalog
/// Description: Relics (persistent modifiers) definitions loaded from JSON at runtime.
/// </summary>
/// <remarks>
/// Related ADRs: ADR-0004 (event bus and contracts), ADR-0005 (quality gates), ADR-0019 (security baseline).
/// Overlay reference: docs/architecture/overlays/PRD-SANGUO-T2/08/08-t62-relics.md.
/// Data source (SSoT): res://Data/relics.json.
/// </remarks>
public sealed record SanguoRelicsCatalog(
    [property: JsonPropertyName("schemaVersion")] int SchemaVersion,
    [property: JsonPropertyName("version")] int Version,
    [property: JsonPropertyName("relics")] IReadOnlyList<SanguoRelicDefinition> Relics
);

/// <summary>
/// DTO: SanguoRelicDefinition
/// Description: Single relic definition. RelicId must be globally unique.
/// </summary>
/// <remarks>
/// EffectKind is restricted by an allow-list in quality gates. This contract stays pure C# (no Godot types).
/// </remarks>
public sealed record SanguoRelicDefinition(
    [property: JsonPropertyName("relicId")] string RelicId,
    [property: JsonPropertyName("nameKey")] string NameKey,
    [property: JsonPropertyName("descriptionKey")] string DescriptionKey,
    [property: JsonPropertyName("effectKind")] string EffectKind,
    [property: JsonPropertyName("moneyDelta")] int? MoneyDelta,
    [property: JsonPropertyName("stepDelta")] int? EconomyStepDelta
);

namespace Game.Core.Contracts.Sanguo;

/// <summary>
/// Serializable snapshot of the Sanguo game runtime state for save/load.
/// </summary>
/// <remarks>
/// This is a contract/DTO (SSoT) and MUST remain Godot-free for fast unit testing.
///
/// Related ADRs: ADR-0006 (data storage), ADR-0004 (event contracts), ADR-0018 (Godot+C# template lineage).
/// </remarks>
public sealed record SanguoSaveSnapshot(
    string GameId,
    int TurnNumber,
    int ActivePlayerIndex,
    int Year,
    int Month,
    int Day,
    IReadOnlyList<string> PlayerOrder,
    IReadOnlyList<SanguoSavePlayer> Players,
    IReadOnlyList<SanguoSaveCityEconomy> CityEconomy,
    long TreasuryMinorUnits,
    string ContentPackId = "",
    int ContentPackVersion = 0,
    IReadOnlyDictionary<string, IReadOnlyDictionary<string, int>>? BuildingLevelsByCityId = null,
    IReadOnlyDictionary<string, IReadOnlyDictionary<string, int>>? ActionCardsByPlayerId = null,
    string RunMode = "campaign",
    string CommanderId = "c_liu_bei",
    int RandomSeed = 0
);

/// <summary>
/// Serializable per-player save data.
/// </summary>
public sealed record SanguoSavePlayer(
    string PlayerId,
    decimal Money,
    int PositionIndex,
    bool IsEliminated,
    IReadOnlyList<string> OwnedCityIds
);

/// <summary>
/// Serializable economy values for a city.
/// </summary>
public sealed record SanguoSaveCityEconomy(
    string CityId,
    decimal BasePrice,
    decimal BaseToll
);

namespace Game.Core.Contracts.Sanguo;

/// <summary>
/// Enum: SanguoTurnPhase
/// Description: High-level turn phase contract used for deterministic action windows.
/// </summary>
/// <remarks>
/// Related ADRs: ADR-0004 (event bus and contracts), ADR-0005 (quality gates).
/// Overlay reference: docs/architecture/overlays/PRD-SANGUO-T2/08/08-feature-slice-t2-setup-map-character-events-cards-buildings-combat-gameend.md.
/// </remarks>
public enum SanguoTurnPhase
{
    /// <summary>
    /// The player may optionally play at most one action card before rolling dice.
    /// </summary>
    BeforeRoll = 0,

    /// <summary>
    /// Dice roll and movement resolution.
    /// </summary>
    RollAndMove = 1,

    /// <summary>
    /// After-move tile actions (buy/build/skip) are resolved.
    /// </summary>
    AfterMove = 2,

    /// <summary>
    /// End-of-turn bookkeeping.
    /// </summary>
    End = 3,
}
